"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import axios from "axios";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";

// 💡 useAuth と useApi をインポート
import { useAuth } from "@/hooks/useAuth";
import { useApi } from "@/hooks/useApi";

// 💡 getImageUrl, onImageError はプロジェクト内の実際のパスに修正してください
import { getImageUrl, onImageError } from "@/utils/utils";

// 環境変数
const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL;

// グローバルなaxiosは、認証が不要なリクエストでのみ使用されます。
// 認証が必要なリクエストは useApi の authenticatedFetch を使用します。
axios.defaults.withCredentials = true;

// =======================================================
// 型定義
// =======================================================

interface Item {
  id: number;
  name: string;
  price: number | null;
  item_image: string | null;
  remain: number;
}

// =======================================================
// メインコンポーネント
// =======================================================

export default function Home() {
  const searchParams = useSearchParams();

  // 1. 認証フックから必要な状態を取得
  const {
    user,
    isLoading: isAuthLoading,
    isLoggingOut,
    isAuthenticated,
  } = useAuth();

  // 2. APIフックから認証済みフェッチ関数を取得
  const { authenticatedFetch } = useApi();

  const [items, setItems] = useState<Item[]>([]);
  const [loading, setLoading] = useState(false); // APIフェッチ中のローディング
  // 画像URLのキャッシュ打破用キー (画像更新時の表示反映用)
  const [imageRefreshKey, setImageRefreshKey] = useState(0);

  // =======================================================
  // Computed (useMemoで代替)
  // =======================================================

  // 現在のタブ状態 ('all' または 'mylist')
  const currentTab = useMemo(() => {
    return searchParams.get("tab") === "mylist" ? "mylist" : "all";
  }, [searchParams]);

  // 現在の検索クエリ
  const currentSearchQuery = useMemo(() => {
    return searchParams.get("all_item_search") || "";
  }, [searchParams]);

  // ページ全体のローディング状態の判定
  const isPageLoading = useMemo(() => {
    // ログアウト処理中、認証状態の解決中、商品データロード中のいずれかが true ならロード中
    return isLoggingOut || isAuthLoading || loading;
  }, [isLoggingOut, isAuthLoading, loading]);

  // テンプレートのログインメッセージ表示に使用
  const isUserLoggedOutComputed = useMemo(() => {
    // 認証が解決済み(isAuthLoading=false)で、かつユーザーが存在しない場合に「ログアウト状態」と判断
    return !isAuthLoading && !user;
  }, [isAuthLoading, user]);

  // =======================================================
  // データフェッチロジック (useCallbackでラップ)
  // =======================================================

  /**
   * 商品データをAPIから取得する関数
   */
  const fetchItems = useCallback(
    async (tab: string, search: string) => {
      // ログアウト処理中はフェッチをスキップ
      if (isLoggingOut) {
        console.log("[Skip Fetch] Logging out, skipping fetch.");
        setItems([]);
        setLoading(false);
        return;
      }

      // マイリストタブかつ未ログインの場合、フェッチをスキップし、空のリストを表示
      if (tab === "mylist" && !isAuthenticated) {
        console.log("[Skip Fetch] Not logged in and accessing mylist.");
        setItems([]);
        setLoading(false);
        setImageRefreshKey((prev) => prev + 1);
        return;
      }

      setLoading(true);

      const apiUrl = `/api/items`;
      const params = { tab: tab, all_item_search: search };

      // 💡 認証クライアントとグローバルAxiosの選択ロジックを再構築
      const useAuthClient = tab === "mylist" || isAuthenticated;

      console.log(
        `[Fetch] Client type: ${
          useAuthClient ? "Authenticated" : "Unauthenticated"
        }. Fetching items: tab=${tab}, search=${search}`
      );

      try {
        let responseData;

        if (useAuthClient) {
          // ★★★ マイリスト または ログイン済みで 'すべて' タブの場合 (認証済みリクエスト) ★★★
          // useApiのauthenticatedFetchは、相対パスと設定を受け取る
          responseData = await authenticatedFetch(apiUrl, {
            method: "GET",
            params: params,
          });
        } else {
          // ★★★ 未ログインで 'すべて' タブの場合 (非認証リクエスト) ★★★
          // グローバルaxiosを使用し、完全なURLを指定
          const response = await axios.get(`${API_BASE_URL}${apiUrl}`, {
            params: params,
          });
          responseData = response.data;
        }

        if (responseData && Array.isArray(responseData.items)) {
          setItems(responseData.items as Item[]);
          setImageRefreshKey((prev) => prev + 1); // 画像リフレッシュ
        } else {
          console.warn("APIレスポンスの構造が不正です:", responseData);
          setItems([]);
        }
      } catch (e: any) {
        // 認証エラーなどで authenticatedFetch がエラーをスローした場合もここでキャッチ
        console.error("商品の取得中に予期せぬエラーが発生しました:", e);
        setItems([]);
      } finally {
        setLoading(false);
      }
    },
    // 依存配列に authenticatedFetch を追加し、useAuth の状態変更によってトークンが更新される度に再実行できるようにする
    [
      isAuthenticated, // ログイン状態が変わった時
      isLoggingOut, // ログアウト中かどうか
      authenticatedFetch, // useApiフックの関数 (useAuthの状態変更に依存)
    ]
  );

  // =======================================================
  // Effect / Watcher (認証状態とURLクエリの統合監視)
  // =======================================================

  useEffect(() => {
    // 認証状態の解決を待つ
    if (isAuthLoading) {
      console.log("[Skip] Waiting for authentication to resolve.");
      setItems([]);
      return;
    }

    // 認証が解決した後、またはクエリ/認証状態が変わったときにフェッチを実行
    console.log(
      `[Fetch Triggered] Auth Resolved/Query Changed. Re-fetching items.`
    );

    fetchItems(currentTab, currentSearchQuery);
  }, [
    currentTab,
    currentSearchQuery,
    isAuthLoading, // 認証完了を監視
    fetchItems, // useCallbackでラップされたfetchItemsを依存配列に追加
  ]);

  // =======================================================
  // レンダリング
  // =======================================================

  return (
    <div className="main_contents">
      {/* ローディング状態表示エリア */}
      {isPageLoading && (
        <div className="flex justify-center items-center h-48">
          <div className="animate-spin rounded-full h-10 w-10 border-4 border-t-4 border-red-500 border-opacity-25 border-t-red-500"></div>
          <p className="ml-4 text-lg text-gray-400">
            {isLoggingOut
              ? "ログアウト処理中..."
              : isAuthLoading
              ? "認証状態を確認中..."
              : "商品を読み込み中..."}
          </p>
        </div>
      )}

      {/* メインコンテンツエリア (ローディング中は非表示) */}
      <div className={isPageLoading ? "hidden" : ""}>
        {/* タブ切り替えコンポーネント */}
        <div className="main_select">
          {/* すべてタブ */}
          <Link
            href={{
              pathname: "/",
              query: {
                tab: "all",
                all_item_search: currentSearchQuery || undefined,
              },
            }}
            className={["recs", { active: currentTab === "all" }]
              .join(" ")
              .replace("false", "")
              .trim()}
          >
            すべて
          </Link>
          {/* マイリストタブ */}
          <Link
            href={{
              pathname: "/",
              query: {
                tab: "mylist",
                all_item_search: currentSearchQuery || undefined,
              },
            }}
            className={["mylists", { active: currentTab === "mylist" }]
              .join(" ")
              .replace("false", "")
              .trim()}
          >
            マイリスト
          </Link>
        </div>

        <div className="items_select">
          {/* 商品リストの表示 */}
          {items.length > 0 ? (
            items.map((item) => (
              <div key={item.id} className="items_select_all">
                {/* 💡 商品詳細ページへのリンク */}
                <Link href={`/items/${item.id}`}>
                  <div className="relative">
                    <img
                      src={getImageUrl(item.item_image, imageRefreshKey)}
                      alt={item.name}
                      onError={(e) => onImageError(e, item.name)}
                      className="w-full aspect-square object-cover block rounded-lg shadow-md"
                    />
                    {/* remainが0の場合にSOLDタグを表示 */}
                    {item.remain === 0 && <div className="sold-text">SOLD</div>}
                  </div>
                  <div className="item-info">
                    <p className="item-name text-gray-100">{item.name}</p>
                    <p className="item-price font-bold text-red-400 text-lg mt-1">
                      &yen;{item.price ? item.price.toLocaleString() : "---"}
                    </p>
                  </div>
                </Link>
              </div>
            ))
          ) : (
            <div className="text-center w-full py-10 text-gray-500">
              <p>
                {currentTab === "mylist" && isUserLoggedOutComputed
                  ? "マイリストを見るにはログインしてください。"
                  : currentTab === "all" && isAuthLoading
                  ? "認証状態を確認中..." // 認証ロード中は認証状態を確認中を表示
                  : "該当する商品が見つかりませんでした。"}
              </p>
            </div>
          )}
        </div>
      </div>

      {/* スタイル定義 (変更なし) */}
      <style jsx>{`
        .main_contents {
          margin: 0 auto;
          max-width: 1400px;
          padding: 0 20px;
        }

        .main_select {
          height: 80px;
          border-bottom: 3px solid #4b5563;
          position: relative;
          display: flex;
          align-items: center;
          justify-content: flex-start;
          padding-left: 100px;
          gap: 50px;
        }

        .recs,
        .mylists {
          text-decoration: none;
          color: #9ca3af;
          font-size: 1.2rem;
          font-weight: bold;
          padding-bottom: 15px;
          border-bottom: 3px solid transparent;
          transition: all 0.3s ease;
          box-sizing: border-box;
        }

        .recs:hover,
        .mylists:hover {
          color: #d1d5db;
        }

        .recs.active,
        .mylists.active {
          color: #ef4444;
          border-bottom: 3px solid #ef4444;
        }

        .items_select {
          display: flex;
          flex-wrap: wrap;
          justify-content: flex-start;
          gap: 40px;
          padding: 80px 0;
        }

        .items_select_all {
          flex: 0 0 calc(25% - 30px);
          box-sizing: border-box;
          position: relative;
          display: flex;
          flex-direction: column;
        }

        @media (max-width: 1024px) {
          .items_select_all {
            flex: 0 0 calc(33.33% - 26.67px);
          }
        }

        @media (max-width: 640px) {
          .items_select_all {
            flex: 0 0 calc(50% - 20px);
          }
          .main_select {
            justify-content: flex-start;
            padding-left: 20px;
            gap: 30px;
          }
        }
        .items_select img {
          box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
        }
        .item-info {
          min-height: 40px;
        }
        .item-name {
          color: #000000ff;
        }

        /* soldタグのスタイル */
        .items_select_all .sold-text {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%, -50%) rotate(-10deg);
          z-index: 10;
          font-size: 1.5rem;
          color: #f87171;
          font-weight: 900;
          padding: 8px 16px;
          background-color: rgba(31, 41, 55, 0.9);
          border: 4px solid #f87171;
          border-radius: 8px;
          box-shadow: 0 0 10px rgba(0, 0, 0, 0.5);
          pointer-events: none;
        }
      `}</style>
    </div>
  );
}
